from rlm import harness
state = harness.get_harness_state()
new_memories = [
    {
        "title": "ARC Task 1558e64b: U-Shape Interior Fill Pattern (grid-2-8-4)",
        "text": "GRID: 23x10, background=2, pattern=8. U-shape pattern at rows 7-10, cols 5-9. Vertical line at col 7, rows 0-21 (separate element).\nRULE: Fill U-shape interior gaps with color 4.\nDETECTION: A U-shape consists of a top solid bar, bottom solid bar, and gap rows in between with arms only (pattern color at column edges, background in interior).\nFILL REGION: All rows between solid bars that are NOT completely solid.\nFILL COLOR: 4 (fixed for this task, not derived from background/pattern).\nEXAMPLES: Left U (rows 3-6 filled), Right U (row 4 filled). ",
        "is_local": False
    },
    {
        "title": "ARC Task 1558e64b: U-Shape Structure Recognition",
        "text": "U-shape detection: Row values at U boundary columns (5 and 9). Solid bar = both columns have pattern across all boundary columns. Gap row = pattern at boundary columns only, background in between.\nFILL INITIATION: Start immediately after top solid bar. Fill continues until hitting bottom solid bar or hitting solid bar.\nVERTICAL LINE: When a vertical line of single cells spans most rows independently, it is NOT part of U-shape pattern and should NOT be modified.\nATTEMPTS: 3 wrong attempts, correct on 4th with rows 8-9 fill.",
        "is_local": False
    }
]

# Save memories
for mem in new_memories:
    state.create_memory(title=mem['title'], text=mem['text'], is_local=mem['is_local'])
    print(f"Created: {mem['title']}")
